 1→/**
 2→ * @cipherbox/sdk - Event system
 3→ *
 4→ * Typed event definitions and a simple emitter for SDK state changes.
 5→ * Consumers subscribe to events to sync external state (e.g., Zustand stores)
 6→ * with SDK-internal state changes.
 7→ *
 8→ * Design: No external dependencies. The emitter is synchronous and
 9→ * subscriber errors are caught to prevent cascading failures.
10→ */
11→
12→import type { FolderChild } from '@cipherbox/core';
13→import type { BinEntry } from '@cipherbox/core';
14→
15→/**
16→ * Union of all events emitted by the SDK.
17→ *
18→ * Events follow the pattern `domain:action` for easy filtering
19→ * by consumers who only care about specific domains.
20→ */
21→export type SdkEvent =
22→  | {
23→      type: 'folder:loaded';
24→      folderId: string;
25→      ipnsName: string;
26→      children: FolderChild[];
27→      sequenceNumber: bigint;
28→    }
29→  | {
30→      type: 'folder:updated';
31→      folderId: string;
32→      ipnsName: string;
33→      children: FolderChild[];
34→      sequenceNumber: bigint;
35→    }
36→  | { type: 'folder:deleted'; folderId: string }
37→  | { type: 'file:uploaded'; folderId: string; fileName: string; cid: string }
38→  | { type: 'file:downloaded'; cid: string }
39→  | { type: 'bin:updated'; entries: BinEntry[] }
40→  | { type: 'share:reWrapFailed'; folderIpnsName: string; failedRecipients: string[] }
41→  | { type: 'operation:start'; operation: string }
42→  | { type: 'operation:end'; operation: string; durationMs: number }
43→  | { type: 'error'; operation: string; error: Error };
44→
45→/**
46→ * Handler function for SDK events.
47→ * Consumers implement this to react to state changes.
48→ */
49→export type SdkEventHandler = (event: SdkEvent) => void;
50→
51→/**
52→ * Simple typed event emitter. No external dependencies.
53→ *
54→ * Consumers subscribe with on() and unsubscribe with off() or the
55→ * returned unsubscribe function. Handler errors are caught silently
56→ * to prevent one subscriber from crashing the SDK or other subscribers.
57→ */
58→export class SdkEventEmitter {
59→  private handlers: SdkEventHandler[] = [];
60→
61→  /**
62→   * Subscribe to all SDK events.
63→   * @returns An unsubscribe function for convenience
64→   */
65→  on(handler: SdkEventHandler): () => void {
66→    this.handlers.push(handler);
67→    return () => this.off(handler);
68→  }
69→
70→  /**
71→   * Unsubscribe a previously registered handler.
72→   */
73→  off(handler: SdkEventHandler): void {
74→    this.handlers = this.handlers.filter((h) => h !== handler);
75→  }
76→
77→  /**
78→   * Emit an event to all subscribers.
79→   * Handler errors are caught and swallowed -- subscriber bugs
80→   * must not crash the SDK.
81→   */
82→  emit(event: SdkEvent): void {
83→    for (const handler of this.handlers) {
84→      try {
85→        handler(event);
86→      } catch {
87→        /* subscriber errors don't crash SDK */
88→      }
89→    }
90→  }
91→
92→  /**
93→   * Remove all handlers. Called during client destroy().
94→   */
95→  removeAll(): void {
96→    this.handlers = [];
97→  }
98→}
