 975→   * Wrap an async operation with event emission and error handling.
 976→   *
 977→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
 978→   * and 'error' on failure. Also calls the config callbacks if provided.
 979→   */
 980→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
 981→    const start = Date.now();
 982→    this.notifySafely(() => this.config.onOperationStart?.(name));
 983→    this.emitter.emit({ type: 'operation:start', operation: name });
 984→
 985→    try {
 986→      const result = await fn();
 987→      const durationMs = Date.now() - start;
 988→      this.notifySafely(() => this.config.onOperationEnd?.(name));
 989→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
 990→      return result;
 991→    } catch (error) {
 992→      this.notifySafely(() => this.config.onError?.(error as Error));
 993→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
 994→      throw error;
 995→    }
 996→  }
 997→
 998→  private notifySafely(fn: () => void): void {
 999→    try {
1000→      fn();
1001→    } catch (err) {
1002→      console.warn('[SDK] Lifecycle callback threw:', err);
1003→    }
1004→  }
1005→}
