if (batchResult.status === 'rejected') {
  const batchError =
    batchResult.reason instanceof Error
      ? batchResult.reason
      : new Error(String(batchResult.reason));
  console.warn(
    '[SDK] File IPNS batch publish failed (non-critical, will retry on next publish):',
